SELECT "users"."id", "users"."email", "users"."name", "users"."nickname", "users"."age", "users"."status", "users"."prev_status", "users"."balance", "users"."score", "users"."is_admin", "users"."tags", "users"."meta", "users"."settings", "users"."external_id", "users"."manager_id", "users"."birthday", "users"."created_at", "orders"."id", "orders"."user_id", "orders"."amount", "orders"."quantity", "orders"."note", "orders"."created_at" FROM "users" LEFT JOIN "users" AS "m" ON "m"."id" = "users"."manager_id" LEFT JOIN "orders" ON "orders"."user_id" = "users"."id"
